#!/usr/bin/env bash
set -euo pipefail
cat > data-story-card-v2.html <<'HTML'
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interactive Outcome Story</title><style>*{box-sizing:border-box}body{margin:0;padding:24px;background:#10141e;color:#f1f4ff;font:14px system-ui}main{max-width:880px;margin:auto}h1{font-size:clamp(25px,4vw,38px);letter-spacing:-.04em;margin:8px 0}p{color:#b1bfd5;line-height:1.6}.eyebrow{font-size:11px;letter-spacing:.15em;color:#9bbaff}.card{background:#192233;border:1px solid #ffffff20;border-radius:16px;padding:18px;margin-top:18px}button{min-height:44px;padding:8px 14px;border:1px solid #ffffff25;border-radius:8px;background:#26344b;color:#eef4ff;cursor:pointer;transition:background .15s,transform .15s}button:hover{background:#354a69}button:active{transform:scale(.96)}button[aria-pressed=true]{border-color:#a6baff;background:#334778}button:focus-visible{outline:2px solid #acd9ff;outline-offset:3px}.controls{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.number{font-variant-numeric:tabular-nums}small{color:#b1bfd5}@media(max-width:500px){body{padding:14px}.card{padding:12px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}</style><main><div class="eyebrow">EVIDENCE NOTEBOOK / TWO COHORTS</div><h1>OpenEval Outcome Story</h1><p>A fixed demonstration dataset. Explore each metric on its own shared scale. These observations show change, not its cause.</p><div class="controls" aria-label="Metric selector"><button data-metric="pass_rate" aria-pressed="false">Pass rate</button><button data-metric="latency" aria-pressed="false">Median latency</button><button data-metric="cost" aria-pressed="false">API equivalent</button><button data-metric="known_bad" aria-pressed="false">Known-bad rejection</button></div><section class="card" aria-live="polite"><h2 id="metric-title">Pass rate</h2><p id="detail">2/5 → 4/5 graded cases</p><div class="bars"><div style="margin:20px 0"><div style="display:flex;justify-content:space-between;gap:12px"><span>Baseline</span><strong id="baseline-value" class="number"></strong></div><div style="height:18px;background:#ffffff0a;border-radius:5px;margin-top:8px;overflow:hidden"><div id="baseline-bar" style="height:100%;background:#a79bf3"></div></div></div><div style="margin:20px 0"><div style="display:flex;justify-content:space-between;gap:12px"><span>Current</span><strong id="current-value" class="number"></strong></div><div style="height:18px;background:#ffffff0a;border-radius:5px;margin-top:8px;overflow:hidden"><div id="current-bar" style="height:100%;background:#8fe1cf"></div></div></div></div><p id="axis"></p><p id="direction"></p><small>Legend: violet = baseline; mint = current. Missing evidence has no bar.</small></section><section class="card"><h2>Dataset and methodology</h2><p>Baseline: pass 2/5; median 4.8s; cost unavailable; known-bad 3/4.<br>Current: pass 4/5; median 3.1s; estimated API equivalent $0.42/case; known-bad 4/4.</p><p>Pass and rejection changes use percentage points. Latency has five measured observations per cohort. Cost is a list-price estimate, not a subscription charge or provider invoice.</p></section><p><small>Reference solution · not an agent result.</small></p></main><script>const metrics={pass_rate:{baseline:40,current:80,unit:'%',lowerIsBetter:false,label:'Pass rate',detail:'2/5 → 4/5 graded cases',max:100},latency:{baseline:4.8,current:3.1,unit:'s',lowerIsBetter:true,label:'Median latency',detail:'5 measured durations in each cohort',max:6},cost:{baseline:null,current:.42,unit:'USD / case',lowerIsBetter:true,label:'API equivalent',detail:'Baseline unavailable; current estimate covers 5/5 cases. Not provider spend.',max:1},known_bad:{baseline:75,current:100,unit:'%',lowerIsBetter:false,label:'Known-bad rejection',detail:'3/4 → 4/4 adversarial cases',max:100}};let metric='pass_rate';
function state(){const m=metrics[metric];return {metric,baseline:m.baseline,current:m.current,unit:m.unit,lowerIsBetter:m.lowerIsBetter};}
function format(v,m){return v===null?'Unavailable':v+' '+m.unit;}
function render(){const m=metrics[metric];document.querySelector('#metric-title').textContent=m.label;document.querySelector('#detail').textContent=m.detail;document.querySelector('#axis').textContent='Shared scale: 0–'+m.max+' '+m.unit;for(const side of ['baseline','current']){const v=m[side];document.querySelector('#'+side+'-value').textContent=format(v,m);document.querySelector('#'+side+'-bar').style.width=v===null?'0%':v/m.max*100+'%';document.querySelector('#'+side+'-bar').hidden=v===null;}document.querySelector('#direction').textContent=m.baseline===null?'Change unavailable: baseline cost was not recorded.':((m.current-m.baseline).toFixed(1)+' '+(m.unit==='%'?'percentage points':m.unit)+' · '+(m.lowerIsBetter?'lower is better':'higher is better'));document.querySelectorAll('[data-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.metric===metric)));}
function select(key){if(!Object.prototype.hasOwnProperty.call(metrics,key))throw new RangeError('Unknown metric');metric=key;render();return state();}window.evaluationDemo={select,reset:()=>select('pass_rate'),getState:state};document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>select(b.dataset.metric));render();</script></html>
HTML
